import { app } from 'electron'
import fs from 'node:fs'
import path from 'node:path'
import { LEGACY_APP_NAMES } from './brand'

/** Regenerated by Chromium on demand; not worth copying. */
const SKIP = new Set(['Cache', 'Code Cache', 'GPUCache', 'DawnGraphiteCache', 'DawnWebGPUCache', 'Crashpad', 'ShaderCache', 'GrShaderCache', 'blob_storage', 'lockfile'])

/**
 * The app's data folder follows its name, so renaming the app would start everyone on an empty
 * profile. On the first run under the new name, copy the old profile across: settings, bookmarks,
 * open tabs, cookies/logins ("Local State" holds the key that decrypts them) and extensions.
 * Must run before anything opens the profile (including the single-instance lock).
 */
function hasProfile(dir: string): boolean {
  return ['settings.json', 'bookmarks.json', 'session.json', 'Partitions'].some((f) => fs.existsSync(path.join(dir, f)))
}

export function migrateLegacyProfile(): void {
  // Electron may already have created the (empty) folder at startup, so look for real profile data.
  const target = app.getPath('userData')
  if (hasProfile(target)) return
  for (const name of LEGACY_APP_NAMES) {
    const source = path.join(app.getPath('appData'), name)
    if (!hasProfile(source)) continue
    const staging = `${target}.migrating`
    try {
      fs.rmSync(staging, { recursive: true, force: true })
      fs.cpSync(source, staging, {
        recursive: true,
        filter: (src) => {
          const base = path.basename(src)
          return !SKIP.has(base) && !base.startsWith('Singleton')
        },
      })
      fs.mkdirSync(target, { recursive: true })
      for (const entry of fs.readdirSync(staging)) {
        const dest = path.join(target, entry)
        if (!fs.existsSync(dest)) fs.renameSync(path.join(staging, entry), dest)
      }
    } catch (err) {
      console.error(`Could not migrate the ${name} profile:`, err)
    } finally {
      fs.rmSync(staging, { recursive: true, force: true })
    }
    return
  }
}
